function parseNpcLocationsFromText(text){const found={},source=String(text||'');chatRoles.forEach(role=>{const escaped=role.name.replace(/[.*+?^$()|[\]\\{}]/g,'\\$&'),direct=new RegExp('["“]?'+escaped+'["”]?\\s*(?:(?:当前)?(?:位置|地点|所在(?:地)?))?\\s*[:：=@＞>→—-]\\s*["“]?([^\\n\\r,，;；|}"”\\]]+)','i'),nested=new RegExp('["“]?'+escaped+'["”]?[^\\n\\r]{0,80}?(?:位置|地点|location)\\s*[:：=]\\s*["“]?([^\\n\\r,，;；|}"”\\]]+)','i'),match=source.match(direct)||source.match(nested);let anchor=match&&resolveMapAnchor(match[1]);if(!anchor){const sentences=source.split(/[。！？!?；;\n\r]/).filter(sentence=>sentence.includes(role.name));for(const sentence of sentences){const after=sentence.slice(sentence.indexOf(role.name)+role.name.length),movement=after.match(/(?:现?在|正在|位于|身处|待在|到了|来到|前往|去往|走向|返回|回到)\s*([^，,]{1,50})/);anchor=movement&&resolveMapAnchor(movement[1]);if(anchor)break}}if(anchor)found[role.id]=anchor});return found}
