function handleSoil(s){const n=s.dataset.index,crop=s.dataset.crop||'';if(fieldTool==='view')return openPlotModal(s);if(fieldTool==='seed'){const item=Object.keys(bagStock('seed')).find(name=>name.replace(/种子$/,'')===seed&&stockLeft('seed',name)>0);if(!item)return toast('背包里没有'+seed+'种子');return applyPlotInventory('seed',item,s)}if(fieldTool==='fertilize'){if(!fertilizerChoice||stockLeft('fertilizer',fertilizerChoice)<1)return openFertilizerPicker();return applyPlotInventory('fertilizer',fertilizerChoice,s)}if(fieldTool==='harvest'){if(!harvestPlot(s))return}if(fieldTool==='water'){if(s.classList.contains('wet'))return toast('第'+n+'格已经浇过水了');s.classList.add('wet');actions.push('给第'+n+'格农田浇水');renderSoil(s);animateSoil(s,'water-flash');toast('第'+n+'格浇水完成')}if(fieldTool==='shovel'){if(!crop)return toast('第'+n+'格没有作物可以铲除');const justPlanted='在第'+n+'格农田播种'+crop;if(!s.dataset.originalCrop&&actions.includes(justPlanted))removeExactAction(justPlanted);else actions.push('铲除第'+n+'格农田的'+crop);s.dataset.crop='';s.dataset.days='';renderSoil(s);animateSoil(s);toast('已铲除第'+n+'格的'+crop)}updateFieldInfo();sync()}
function undoFieldAction(a){let m=a.match(/^在第(\d+)格农田播种(.+)$/);if(m){const s=$$('#field .soil')[+m[1]-1];if(s){s.dataset.crop='';renderSoil(s);animateSoil(s)}}m=a.match(/^给第(\d+)格农田浇水$/);if(m){const s=$$('#field .soil')[+m[1]-1];if(s){s.classList.toggle('wet',s.dataset.originalWet==='1');renderSoil(s)}}m=a.match(/^铲除第(\d+)格农田的(.+)$/);if(m){const s=$$('#field .soil')[+m[1]-1];if(s){s.dataset.crop=m[2];renderSoil(s);animateSoil(s)}}}
function rebuildFieldState(){const expanded=actions.filter(a=>/^扩充第\d+格耕地$/.test(a)).length;$('#field').innerHTML='';for(let i=0;i<24;i++)makeSoil(i<8?'土豆':i<14?'郁金香':'',i<7,false,i<2?0:null);for(let i=0;i<expanded;i++)makeSoil('',false,true);actions.forEach(a=>{let m=a.match(/^在第(\d+)格农田播种(.+)$/);if(m){const s=$$('#field .soil')[+m[1]-1];if(s){s.dataset.crop=m[2];s.dataset.days=cropDays(m[2]);renderSoil(s)}}m=a.match(/^给第(\d+)格农田浇水$/);if(m){const s=$$('#field .soil')[+m[1]-1];if(s){s.classList.add('wet');renderSoil(s)}}m=a.match(/^给第(\d+)格农田施用(.+)$/);if(m){const s=$$('#field .soil')[+m[1]-1];if(s){s.dataset.fertilizer=m[2];renderSoil(s)}}m=a.match(/^铲除第(\d+)格农田的(.+)$/);if(m){const s=$$('#field .soil')[+m[1]-1];if(s){s.dataset.crop='';s.dataset.days='';renderSoil(s)}}m=a.match(/^收获第(\d+)格农田的(.+)$/);if(m){const s=$$('#field .soil')[+m[1]-1];if(s){s.dataset.crop='';s.dataset.days='';renderSoil(s)}}});setFieldTool(fieldTool,seed);updateFieldInfo()}
function cancelActionAt(i){if(i<0||i>=actions.length)return'';const a=actions.splice(i,1)[0],expanded=a.match(/^扩充第(\d+)格耕地$/);if(expanded){const from=+expanded[1];for(let n=actions.length-1;n>=0;n--){const m=actions[n].match(/第(\d+)格(?:农田|耕地)/);if(m&&+m[1]>=from)actions.splice(n,1)}}rebuildFieldState();return a}
for(let i=0;i<24;i++)makeSoil(i<8?'土豆':i<14?'郁金香':'',i<7,false,i<2?0:null);updateFieldInfo();renderSeedToolbar();$('#waterTool').onclick=()=>setFieldTool(fieldTool==='water'?'view':'water');$('#fertilizeTool').onclick=openFertilizerPicker;$('#shovelTool').onclick=()=>setFieldTool(fieldTool==='shovel'?'view':'shovel');$('#harvestTool').onclick=()=>setFieldTool(fieldTool==='harvest'?'view':'harvest');$('#harvestAll').onclick=()=>{const ready=[...$$('#field .soil.mature')];if(!ready.length)return toast('目前没有成熟作物');ready.forEach(s=>harvestPlot(s,true));updateFieldInfo();sync();toast('已收获 '+ready.length+' 块成熟农田')};$('#seedPickerConfirm').onclick=()=>{selectedSeeds=[...seedDraft].filter(name=>stockLeft('seed',name)>0);renderSeedToolbar();$('#seedPickerModal').classList.remove('show');toast(selectedSeeds.length?'种子已放入快捷栏':'快捷栏保持为空')};$('#fertilizerPickerConfirm').onclick=()=>{if(!fertilizerDraft||stockLeft('fertilizer',fertilizerDraft)<1)return toast('请先选择可用肥料');fertilizerChoice=fertilizerDraft;setFieldTool('fertilize');$('#fertilizerPickerModal').classList.remove('show');toast('已选择'+fertilizerChoice)};$('#fertilizerToolCancel').onclick=()=>{fertilizerChoice='';fertilizerDraft='';setFieldTool('view');$('#fertilizerPickerModal').classList.remove('show');toast('已取消施肥工具')};$('#expandField').onclick=()=>{const n=$$('#field .soil').length+1;makeSoil('',false,true);actions.push('扩充第'+n+'格耕地');sync();showPlotPop($$('#field .soil')[n-1],'第'+n+'格 · 新耕地');toast('第'+n+'格新耕地已经翻好了！')};
$$('.plot-action').forEach(b=>b.onclick=()=>{if(!plotTarget)return;const kind=b.dataset.plotAction,n=plotTarget.dataset.index,crop=plotTarget.dataset.crop||'';if(kind==='seed'||kind==='fertilize'){drawPlotModal(kind==='seed'?'seed':'fertilizer');return}if(kind==='water'){plotTarget.classList.add('wet');actions.push('给第'+n+'格农田浇水');renderSoil(plotTarget);animateSoil(plotTarget,'water-flash');toast('第'+n+'格浇水完成')}if(kind==='shovel'){const justPlanted='在第'+n+'格农田播种'+crop;if(!plotTarget.dataset.originalCrop&&actions.includes(justPlanted))removeExactAction(justPlanted);else actions.push('铲除第'+n+'格农田的'+crop);plotTarget.dataset.crop='';plotTarget.dataset.days='';renderSoil(plotTarget);animateSoil(plotTarget);toast('已铲除第'+n+'格的'+crop)}if(kind==='harvest')harvestPlot(plotTarget);updateFieldInfo();sync();drawPlotModal()});$$('.bag-link').forEach(b=>b.onclick=()=>{$('#fieldModal').classList.remove('show');$('#fieldApp').classList.remove('active');$('#bag').classList.add('active');toast('已打开背包，种子与肥料库存会同步到农田')});
function drawCraftQty(){$('#craftQty').textContent=craftQty;$('#craftLimit').textContent='当前材料最多可以制作 '+craftMax+' 个'}
$$('.recipe:not(.locked)').forEach(r=>r.onclick=()=>{craftName=r.dataset.name;craftMax=+r.dataset.max;craftQty=1;$('#craftTitle').textContent='制作 '+craftName;$('#craftMaterials').textContent=r.dataset.materials.replace(/\\n/g,'\n');drawCraftQty();$('#craftModal').classList.add('show')});$('#craftMinus').onclick=()=>{craftQty=Math.max(1,craftQty-1);drawCraftQty()};$('#craftPlus').onclick=()=>{craftQty=Math.min(craftMax,craftQty+1);drawCraftQty()};$('#craftConfirm').onclick=()=>{const old=actions.findIndex(a=>a.startsWith('制作'+craftName+'×'));if(old>=0)actions.splice(old,1);actions.push('制作'+craftName+'×'+craftQty);sync();toast('已加入制作清单');$('#craftModal').classList.remove('show')};
function fieldSummary(){const crops={},harvests={};actions.forEach(a=>{let m=a.match(/^在第\d+格农田播种(.+)$/);if(m)crops[m[1]]=(crops[m[1]]||0)+1;m=a.match(/^收获第\d+格农田的(.+)$/);if(m)harvests[m[1]]=(harvests[m[1]]||0)+1});const cropText=Object.entries(crops).map(([name,count])=>'播种了'+count+'个'+name).join('、')||'本轮未播种',harvestText=Object.entries(harvests).map(([name,count])=>'收获了'+count+'个'+name).join('、')||'本轮未收获',expanded=actions.filter(a=>/^扩充第\d+格耕地$/.test(a)).length,watered=actions.filter(a=>/^给第\d+格农田浇水$/.test(a)).length,fertilized=actions.filter(a=>/^给第\d+格农田施用/.test(a)).length,plots=[...$$('#field .soil')],empty=plots.filter(s=>!s.dataset.crop).length,dry=plots.filter(s=>!s.classList.contains('wet')).length;return cropText+'；'+harvestText+'；扩充了'+expanded+'格耕地；浇了'+watered+'块农田；施肥了'+fertilized+'块农田；操作后共'+plots.length+'格，其中'+empty+'格未播种、'+dry+'格未浇水'}
$$('.undo').forEach(b=>{b.textContent='取消';b.onclick=()=>{if(!actions.length)return toast('没有可以取消的操作');const a=cancelActionAt(actions.length-1);toast('已取消：'+a);sync()}});function renderSummary(){if(!actions.length){$('#summaryList').textContent='行动篮还是空的。';$('#send').style.display='none';return}const f=finance();$('#send').style.display='block';$('#send').textContent=f.balance<0?'余额不足':'整合发送';$('#send').classList.toggle('send-blocked',f.balance<0);$('#summaryList').innerHTML=actions.map((a,i)=>'<div class="summary-item"><span>'+(i+1)+'. '+a+'</span><button class="remove" data-i="'+i+'">取消</button></div>').join('')+'<div class="field-summary-box"><b>农田总结</b>'+fieldSummary()+'</div><div class="finance-box"><div class="finance-row"><span>当前金币</span><b>'+baseFunds.toLocaleString('zh-CN')+'g</b></div><div class="finance-row income"><span>出售收入</span><b>+'+f.income.toLocaleString('zh-CN')+'g</b></div><div class="finance-row expense"><span>购买与扩充支出</span><b>−'+f.expense.toLocaleString('zh-CN')+'g</b></div><div class="finance-row total"><span>操作后预计余额</span><b class="balance">'+f.balance.toLocaleString('zh-CN')+'g</b></div></div>';$$('.remove').forEach(b=>b.onclick=()=>{cancelActionAt(+b.dataset.i);sync();renderSummary()})}function openSummary(){renderSummary();$('#summaryModal').classList.add('show')}$$('.summary').forEach(b=>b.onclick=openSummary);$('#summaryIcon').onclick=openSummary;$$('.close').forEach(b=>b.onclick=()=>b.closest('.modal').classList.remove('show'));
$('#send').onclick=async()=>{const f=finance();if(f.balance<0){$('#warningAmount').textContent='还缺少 '+Math.abs(f.balance).toLocaleString('zh-CN')+'g';$('#warningModal').classList.add('show');return}const msg='【今日农场行动】'+actions.join('；')+'。农田总结：'+fieldSummary()+'。当前金币：'+baseFunds+'g；出售收入：'+f.income+'g；购买与扩充支出：'+f.expense+'g；全部操作完成后的金币：'+f.balance+'g。请执行操作并更新农场状态。';if(typeof triggerSlash==='function'){triggerSlash('/send '+msg);await new Promise(r=>setTimeout(r,150));triggerSlash('/trigger')}else navigator.clipboard?.writeText(msg);$('#summaryModal').classList.remove('show');toast(typeof triggerSlash==='function'?'已发送':'指令已复制')};
// Independent decorative pets: no inventory, affection, or action-queue mutations.
(function initPetMeadow(){
 const stage=$('.pet-meadow'),app=$('#animal');if(!stage)return;
 const doc=stage.ownerDocument,win=doc.defaultView,reduce=win.matchMedia('(prefers-reduced-motion: reduce)'),pause=stage.querySelector('.pet-pause');
 let paused=reduce.matches,raf=0,last=0,clock=0,layoutWidth=0;
 const pets=[...stage.querySelectorAll('.meadow-pet')].map((el,i)=>({el,sprite:el.querySelector('i'),i,x:0,y:0,tx:0,ty:0,wait:i*.2,dir:1,happy:0,speed:[34,28,37,32,43][i]}));
 const bounds=()=>Math.max(0,stage.clientWidth-64),depth=()=>Math.max(100,stage.clientHeight-49);
 function target(p){p.tx=p.x<bounds()/2?bounds()*(.65+Math.random()*.35):bounds()*Math.random()*.35;p.ty=94+Math.random()*(depth()-94)}
 function layout(){if(stage.clientWidth<=64||layoutWidth===stage.clientWidth)return;layoutWidth=stage.clientWidth;pets.forEach((p,i)=>{p.x=bounds()*[.02,.5,.96,.24,.75][i];p.y=[95,125,98,159,163][i];p.y=Math.min(depth(),p.y);target(p);draw(p,false)})}
 function draw(p,walk){p.el.style.transform='translate('+Math.round(p.x)+'px,'+Math.round(p.y)+'px)';p.el.style.zIndex=String(Math.round(p.y));const f=walk?Math.floor(clock*(p.i===4?3:5)+p.i)%2:0;p.sprite.style.backgroundPosition=(-f*64)+'px '+(-p.i*48)+'px';p.sprite.style.transform='scaleX('+p.dir+') translateY('+(walk?(p.i===4?-Math.abs(Math.sin(clock*8))*5:-Math.abs(Math.sin(clock*13))):0)+'px)';p.el.classList.toggle('is-happy',p.happy>0)}
 function visible(){return stage.isConnected&&app.classList.contains('active')&&!doc.hidden&&stage.getBoundingClientRect().width>0}
 function tick(now){raf=0;if(paused||!visible()){last=0;return}if(last&&now-last<40){raf=win.requestAnimationFrame(tick);return}const dt=last?Math.min((now-last)/1000,.1):0;last=now;clock+=dt;
 pets.forEach(p=>{p.happy=Math.max(0,p.happy-dt);let walk=false;if(p.happy<=0){if(p.wait>0)p.wait-=dt;else{let dx=p.tx-p.x,dy=p.ty-p.y,d=Math.hypot(dx,dy);if(d<4){p.wait=.4+Math.random()*1.4;target(p)}else{let vx=dx/d,vy=dy/d;
 // Soft depth steering lets pets pass each other instead of locking horizontal order.
 pets.forEach(q=>{if(q===p)return;const ax=p.x-q.x,ay=p.y-q.y;if(Math.abs(ax)<49&&Math.abs(ay)<30){vy+=(ay===0?(p.i<q.i?-1:1):Math.sign(ay))*(1-Math.abs(ax)/49)*1.5}});
 const norm=Math.hypot(vx,vy)||1;p.x=Math.max(0,Math.min(bounds(),p.x+vx/norm*p.speed*dt));p.y=Math.max(94,Math.min(depth(),p.y+vy/norm*p.speed*dt));if(Math.abs(dx)>2)p.dir=dx>0?1:-1;walk=true}}}draw(p,walk)});raf=win.requestAnimationFrame(tick)}
 function refresh(){layout();pause.textContent=paused?'▶':'Ⅱ';pause.setAttribute('aria-label',paused?'开始动物散步':'暂停动物散步');if(raf)win.cancelAnimationFrame(raf);raf=0;last=0;if(!paused&&visible())raf=win.requestAnimationFrame(tick);else pets.forEach(p=>draw(p,false))}
 pets.forEach(p=>p.el.addEventListener('click',()=>{p.happy=1.5;p.wait=.4;draw(p,false);win.setTimeout(()=>{p.happy=0;p.el.classList.remove('is-happy')},1500)}));
 pause.addEventListener('click',()=>{paused=!paused;refresh()});
 const observer=new win.MutationObserver(refresh);observer.observe(app,{attributes:true,attributeFilter:['class']});
 doc.addEventListener('visibilitychange',refresh);
 if(win.ResizeObserver)new win.ResizeObserver(refresh).observe(stage);
 refresh();
})();

