const originalSync=sync;
cropDays=function(crop){const row=[...$$('.sale-row[data-kind="seed"]')].find(r=>r.dataset.name.replace(/种子$/,'')===crop);const days=Number(row?.dataset.days);return Number.isFinite(days)&&days>0?days:'';};
