function capturePlots(){return [...$$('#field .soil')].map(s=>({crop:s.dataset.crop||'',days:s.dataset.days===''?null:Number(s.dataset.days),wet:s.classList.contains('wet'),fertilizer:s.dataset.fertilizer||''}));}
function captureDraft(){return {actions:[...actions],plots:capturePlots()};}
const initial={gold:0,capacity:24,calendar:{season:'未确认',day:0,year:0,time:'--:--',weather:'未确认',weekday:''},inventory:[],plots:Array.from({length:24},()=>({crop:'',days:null,wet:false,fertilizer:''})),relationships:Object.fromEntries(chatRoles.map(r=>[r.id,0])),locations:{},quests:[],animals:[],buildings:[],calendarEvents:[],notes:''};
function drawPlots(plots){$('#field').replaceChildren();plots.forEach(p=>{makeSoil(p.crop,p.wet,false,p.days);const s=$$('#field .soil')[$$('#field .soil').length-1];s.dataset.fertilizer=p.fertilizer||'';s.dataset.originalFertilizer=p.fertilizer||'';s.dataset.days=p.days==null?'':String(p.days);if(p.stage&&p.stage!=='mature'&&s.dataset.days==='0')s.dataset.days='';s.dataset.originalDays=s.dataset.days;renderSoil(s);});updateFieldInfo();}
function drawInventory(){
  $('#bagList').innerHTML=liveState.inventory.map(r=>'<div class="row sale-row" data-name="'+esc(r.name)+'" data-count="'+r.count+'" data-price="'+(r.price||0)+'" data-kind="'+(r.kind||'item')+'" data-days="'+(r.days||0)+'" data-qty="1"><div class="main"><span class="bag-select"></span><div><h3>'+esc(r.name)+' <span class="item-count">×'+r.count+'</span></h3><div class="sub">'+(r.kind==='seed'?(r.days||'?')+' 天成熟 · ':'')+(r.price||0)+'g / 个</div></div><div class="item-tools"><button class="qty-step" data-d="-1">−</button><span class="qty-num">1</span><button class="qty-step" data-d="1">＋</button><button class="btn sell-one">出售</button></div></div></div>').join('');
  $$('.qty-step').forEach(b=>b.onclick=()=>{const r=b.closest('.sale-row');const q=Math.max(1,Math.min(+r.dataset.count,+r.dataset.qty+ +b.dataset.d));r.dataset.qty=q;r.querySelector('.qty-num').textContent=q;});
  $$('.sell-one').forEach(b=>b.onclick=()=>{const r=b.closest('.sale-row');if(+r.dataset.count===0)return toast('物品数量为零');const a='出售'+r.dataset.name+'×'+r.dataset.qty+'（'+(+r.dataset.qty*+r.dataset.price)+'g）';if(r.dataset.saleAction){removeExactAction(r.dataset.saleAction);r.dataset.saleAction='';}else{actions.push(a);r.dataset.saleAction=a;}sync();});
  $$('.sale-row').forEach(r=>r.onclick=e=>{if(selecting&&!e.target.closest('button'))r.classList.toggle('batch-on');});
}
rebuildFieldState=function(){if(!liveState)return;drawPlots(liveState.plots);for(const a of actions){let m=a.match(/第(\d+)格/);if(!m)continue;const i=+m[1]-1;if(a.startsWith('扩充')){if(!$$('#field .soil')[i])makeSoil();continue;}const s=$$('#field .soil')[i];if(!s)continue;if(a.includes('播种')){s.dataset.crop=a.split('播种')[1];s.dataset.days=cropDays(s.dataset.crop);}if(a.includes('浇水'))s.classList.add('wet');if(a.includes('施用'))s.dataset.fertilizer=a.split('施用')[1];if(a.startsWith('收获')||a.startsWith('铲除')){s.dataset.crop='';s.dataset.days='';}renderSoil(s);}updateFieldInfo();};
$('#bagUpgrade').onclick=()=>{const capacity=liveState.capacity+12;if(actions.some(a=>a.startsWith('扩充背包')))return toast('本轮已安排扩充');if(finance().balance<2000)return toast('金币不足 2000g');toggle('扩充背包至'+capacity+'格（支出2000g）');};
normalizeBagUpgrades=function(){};
renderChatRoom=function(role){activeRole=role;unread[role.id]=false;bridge.read?.(role.id);const body=$('#chatRoom .chat-room-body');$('#chatRoomName').textContent=role.name;const messages=histories[role.id]||[];body.classList.add('has-messages');body.innerHTML=messages.length?messages.map(m=>'<div class="chat-message '+(m.from==='me'?'outgoing':'incoming')+'">'+(m.from==='me'?'':'<span class="chat-avatar">'+portraitMarkup(role)+'</span>')+'<div class="chat-message-content"><div class="chat-bubble">'+esc(m.text)+'</div><span class="chat-message-time">'+esc(m.time||'')+(m.from==='me'?' · '+({queued:'已发送 · 等待触发回复',sending:'对方正在输入',failed:'回复失败，可重试',sent:'已送达'}[m.status]||'已送达'):'')+'</span></div></div>').join(''):'<div class="jp-live-note">写下第一条消息，和'+esc(role.name)+'聊天吧。</div>';body.scrollTop=body.scrollHeight;};
renderChatThreads=function(){const query=$('#chatSearch').value.trim();$('#chatThreads').innerHTML=chatRoles.filter(r=>(r.name+r.job).includes(query)).map(r=>{const last=histories[r.id]?.at(-1);return '<button class="chat-thread" data-role="'+r.id+'"><span class="chat-avatar">'+portraitMarkup(r)+'</span><span class="chat-thread-main"><span class="chat-thread-name">'+r.name+(unread[r.id]?' ●':'')+'<em>'+r.job+'</em></span><span class="chat-thread-preview">'+esc(last?.text?.slice(0,42)||'尚无消息')+'</span></span><span class="chat-thread-end">›</span></button>';}).join('');$$('#chatThreads .chat-thread').forEach(b=>b.onclick=()=>{renderChatRoom(chatRoles.find(r=>r.id===b.dataset.role));$('#chatListView').hidden=true;$('#chatRoom').hidden=false;$('#chatApp').classList.add('chat-room-open');});};
// Replace the previously captured search callback.
$('#chatSearch').addEventListener('input',()=>queueMicrotask(renderChatThreads));

const composer=$('.chat-composer input'),sendButton=$('.chat-composer button');composer.disabled=false;sendButton.disabled=false;sendButton.textContent='虚拟发送';sendButton.setAttribute('aria-label','虚拟发送');
const realSend=uiDocument.createElement('button');realSend.className='jp-real-send';realSend.textContent='真正发送';realSend.setAttribute('aria-label','真正发送');$('.chat-composer').append(realSend);
async function stageBubble(){if(!activeRole||!composer.value.trim())return;const text=composer.value.trim(),role=activeRole;composer.value='';try{await bridge.queueBubble(role,text);}catch(e){composer.value=text;toast(e.message);}}
sendButton.onclick=stageBubble;composer.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.isComposing){e.preventDefault();stageBubble();}});
realSend.onclick=async()=>{if(!activeRole)return;const role=activeRole;realSend.disabled=true;try{await stageBubble();await bridge.send(role);}catch(e){toast(e.message);}finally{realSend.disabled=false;}};
$('#send').textContent='放入酒馆输入框';$('#send').onclick=()=>{if(!actions.length)return toast('行动篮是空的');if(finance().balance<0)return toast('预计金币不足');try{bridge.compose('【今日农场行动】'+actions.join('；')+'。农田预览：'+fieldSummary()+'。请根据实际演绎结果更新农场状态。');$('#summaryModal').classList.remove('show');toast('已放入酒馆输入框，发送正文后结算');}catch(e){toast(e.message);}};
