function bindGiftButtons(){$$('.gift-open').forEach(b=>b.onclick=()=>{giftPerson=b.dataset.person;giftChoice='';$('#giftList').innerHTML=liveState.inventory.filter(x=>x.count>0).map(x=>'<button class="gift" data-gift="'+esc(x.name)+'">'+esc(x.name)+' ×'+x.count+'</button>').join('');$$('#giftList .gift').forEach(g=>g.onclick=()=>{giftChoice=g.dataset.gift;$$('#giftList .gift').forEach(x=>x.classList.toggle('selected',x===g));});$('#giftModal').classList.add('show');});}
function update(state,threads,flags,draft){applying=true;try{
 liveState=structuredClone(state);baseFunds=state.gold;actions.splice(0,actions.length,...(draft?.actions||[]));drawInventory();drawPlots(draft?.plots||state.plots);
 const d=state.calendar,date=d.day?d.season+' '+d.day+' 日':'日期未确认';$('.home-title h1').textContent=d.time;$('.date-widget').textContent=[d.weather,date,d.weekday].filter(Boolean).join(' · ');$('.status span').textContent=d.time;$('.status .weather').textContent=date;
 $('#dateApp .app-head span').textContent=date;
 $('#dateApp .app-body').innerHTML='<div class="row calendar"><div class="date"><b>今天</b><strong>'+esc(d.day||'—')+'</strong></div><div><h3>'+esc(date)+'</h3><div class="sub">'+esc(d.weekday)+' · '+esc(d.time)+' · '+esc(d.weather)+'</div></div></div>'+(state.calendarEvents||[]).map(e=>'<div class="row calendar"><div class="date"><b>'+esc(e.season||d.season)+'</b><strong>'+e.day+'</strong></div><div><h3>'+esc(e.name)+'</h3><div class="sub">'+esc(e.detail||'')+'</div>'+(e.person?'<button class="btn gift-open" data-person="'+esc(e.person)+'">选择礼物</button>':'')+'</div></div>').join('')+'<p class="tip">生日、节日和日程随正文变量更新。</p>';bindGiftButtons();
 $('#quest .app-head span').textContent=state.quests.length+' 项';$('#quest .app-body .list').innerHTML=state.quests.map((q,i)=>'<div class="row quest" data-q="'+i+'"><div class="main"><div><h3>'+esc(q.name)+'</h3><div class="sub">'+esc(q.status)+'</div>'+(Number.isFinite(q.progress)?'<div class="progress"><i style="width:'+Math.max(0,Math.min(100,q.progress))+'%"></i></div>':'')+'</div><span class="tag pink">'+esc(q.deadline||'查看详情')+'</span></div></div>').join('')||'<p class="tip">尚无任务。</p>';
 $$('[data-q]').forEach(b=>b.onclick=()=>{const q=state.quests[+b.dataset.q];currentQuest='完成任务：'+q.name;$('#questTitle').textContent=q.name;$('#questDetail').textContent=[q.detail,q.goal?'目标：'+q.goal:'',q.status,q.deadline?'期限：'+q.deadline:''].filter(Boolean).join('\n\n');$('#questReward').textContent=q.reward||'奖励尚未确认';$('#questAdd').textContent=actions.includes(currentQuest)?'取消提交':'提交任务';$('#questModal').classList.add('show');});
 const count=name=>state.inventory.filter(x=>x.name===name).reduce((n,x)=>n+x.count,0);const buildings=state.buildings||[];const lists=$$('#farm .farm-text-list');lists[0].innerHTML=buildings.map(b=>'<div class="row"><div class="main"><div><h3>'+esc(b.name)+' <span class="farm-status">'+esc(b.status)+'</span></h3>'+(Number.isFinite(b.progress)?'<div class="progress"><i style="width:'+Math.max(0,Math.min(100,b.progress))+'%"></i></div>':'')+'</div></div></div>').join('')||'<p class="tip">尚无已确认建筑。</p>';
 lists[1].innerHTML=[{name:'畜棚',price:6000,needs:{木材:350,石头:150}},{name:'鱼塘',price:5000,needs:{石头:200,海草:5}}].map(b=>{const enough=state.gold>=b.price&&Object.entries(b.needs).every(([k,v])=>count(k)>=v);return '<div class="row"><div class="main"><div><h3>'+b.name+'</h3><p class="farm-description">为农场添点新东西。</p><div class="farm-materials">'+Object.entries(b.needs).map(([k,v])=>'<span class="'+(count(k)<v?'shortage':'')+'">'+k+' <b>'+count(k)+' / '+v+'</b></span>').join('')+'</div></div><span class="farm-price">'+b.price+'g</span><button class="btn" data-build="'+b.name+'" data-price="'+b.price+'" '+(enough?'':'disabled')+'>'+(enough?'购买':'材料不足')+'</button></div></div>';}).join('');$$('[data-build]').forEach(b=>b.onclick=()=>toggle('购买并建造'+b.dataset.build+'（支出'+b.dataset.price+'g）'));
 const recipes=[{name:'木箱',needs:{木材:50}},{name:'稻草人',needs:{木材:50,煤炭:1,纤维:20}},{name:'熔炉',needs:{铜矿石:20,石头:25}},{name:'蜂房',needs:{煤炭:8,铁锭:1}}];$('#craft .app-head span').textContent='材料来自背包';$('#craft .recipe-grid').innerHTML=recipes.map(r=>{const max=Math.min(...Object.entries(r.needs).map(([k,n])=>Math.floor(count(k)/n)));return '<div class="recipe '+(max?'':'locked')+'" data-recipe="'+r.name+'" data-max="'+max+'"><h3>'+r.name+'</h3><div class="materials">'+Object.entries(r.needs).map(([k,n])=>k+' '+count(k)+' / '+n).join(' · ')+'</div><div class="'+(max?'can':'no')+'">'+(max?'最多制作 '+max+' 个':'材料不足')+'</div></div>';}).join('');$$('[data-recipe]').forEach(r=>r.onclick=()=>{if(!+r.dataset.max)return;craftName=r.dataset.recipe;craftMax=+r.dataset.max;craftQty=1;$('#craftTitle').textContent='制作 '+craftName;$('#craftMaterials').textContent=r.querySelector('.materials').textContent;drawCraftQty();$('#craftModal').classList.add('show');});
 $('#animal .app-head span').textContent=state.animals.length+' 位伙伴';$('#animal .animal-scene').hidden=!state.animals.length;$('#animal .app-body > .list').innerHTML=state.animals.map(a=>'<div class="animal-unit"><div class="row"><div class="main"><div><h3>'+esc(a.name)+'</h3><div class="sub">'+esc(a.status)+'</div></div></div></div><div class="animal-actions"><button class="btn" data-animal="'+esc(a.name)+'">安排照料</button></div></div>').join('');$$('[data-animal]').forEach(b=>b.onclick=()=>toggle('照料'+b.dataset.animal));
 chatRoles.forEach(r=>r.friendship=state.relationships[r.id]||0);Object.keys(mapNpcLocations).forEach(k=>delete mapNpcLocations[k]);Object.assign(mapNpcLocations,state.locations);mapHasLiveLocations=true;renderMapNpcLocations();updateMapLocationCaption();
 histories=threads;unread=flags;renderChatThreads();if(activeRole&&!$('#chatRoom').hidden)renderChatRoom(activeRole);renderChatAffection();renderSeedToolbar();sync();
}finally{applying=false;}}
return {initial,mapAnchors:mapLocationAnchors,roles:chatRoles.map(({id,name,job})=>({id,name,job})),update,toast,home:goHome,settingsBody:settingsApp.querySelector('.jp-settings-body'),statusLine:settingsApp.querySelector('.jp-settings-status'),dragHandles:[$('.status'),$('.speaker'),$('.device')],showSettings(){goHome();$('#home').style.display='none';$('#screen').classList.add('app-open');settingsApp.classList.add('active');},setStatus(text){settingsApp.querySelector('.jp-settings-status').textContent=text;$('.home-title p').textContent=text;},setLoreStatus(text){const info=settingsApp.querySelector('.jp-lore-info');if(info)info.textContent=text;},notify(text){notice.textContent=text;notice.classList.add('show');setTimeout(()=>notice.classList.remove('show'),6000);},closeRoom(){activeRole=null;notice.classList.remove('show');$('#chatRoomBack').click();},getDraft:captureDraft};

